### Turn 8 (step_num=8)
**Phase:** ACP tool call
**Response:** 
**Action:** file_editor: {"command": "create", "path": "/root/output/js/visualization.js", "file_text": "// Stock sector bubble chart + linked table.
// Bubbles are sized by market cap (uniform for ETFs), colored by sector,
// clustered by sector using forceX/forceY, and kept apart with forceCollide.

const WIDTH = 740;
const HEIGHT = 640;

const SECTORS = ["Information Technology", "Financial", "Industry", "Energy", "ETF"];

// Distinct, colorblind-friendlyish palette; stable per sector.
const SECTOR_COLORS = {
    "Information Technology": "#2563eb",
    "Financial":              "#059669",
    "Industry":               "#d97706",
    "Energy":                 "#dc2626",
    "ETF":                    "#7c3aed"
};

const color = sector => SECTOR_COLORS[sector] || "#6b7280";

// Deterministic cluster centers arranged around the chart's center so
// clusters stay close together rather than pinned to the corners.
function clusterCenters(width, height) {
    const cx = width / 2;
    const cy = height / 2;
    const r = Math.min(width, height) * 0.24;
    const centers = {};
    SECTORS.forEach((s, i) => {
        const angle = (i / SECTORS.length) * 2 * Math.PI - Math.PI / 2;
        centers[s] = { x: cx + r * Math.cos(angle), y: cy + r * Math.sin(angle) };
    });
    return centers;
}

function formatMarketCap(v) {
    if (v == null || isNaN(v) || v === 0) return "—";
    const abs = Math.abs(v);
    if (abs >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (abs >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
    if (abs >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
    return d3.format(",")(v);
}

d3.csv("data/stock-descriptions.csv", d => ({
    ticker:    d.ticker,
    sector:    d.sector,
    name:      d["full name"],
    marketCap: d.marketCap ? +d.marketCap : null,
    country:   d.country || "",
    website:   d.website || ""
})).then(stocks => {
    render(stocks);
});

function render(stocks) {
    // Radius scale: sqrt so bubble AREA is proportional to market cap.
    const marketCapValues = stocks.filter(s => s.marketCap).map(s => s.marketCap);
    const radius = d3.scaleSqrt()
        .domain([d3.min(marketCapValues), d3.max(marketCapValues)])
        .range([14, 52]);

    const ETF_RADIUS = 20;
    stocks.forEach(s => {
        s.r = s.sector === "ETF" ? ETF_RADIUS : radius(s.marketCap);
    });

    const centers = clusterCenters(WIDTH, HEIGHT);

    buildLegend();
    const bubbleApi = buildBubbleChart(stocks, centers);
    const tableApi  = buildTable(stocks);

    // Two-way selection between bubbles and table rows.
    function select(ticker) {
        bubbleApi.highlight(ticker);
        tableApi.highlight(ticker);
    }
    bubbleApi.onSelect(select);
    tableApi.onSelect(select);
}

function buildLegend() {
    const legend = d3.select("#legend");
    legend.selectAll(".legend-item")
        .data(SECTORS)
        .join("div")
        .attr("class", "legend-item")
        .html(s => `<span class="legend-swatch" style="background:${color(s)}"></span>${s}`);
}

function buildBubbleChart(stocks, centers) {
    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("viewBox", `0 0 ${WIDTH} ${HEIGHT}`)
        .attr("preserveAspectRatio", "xMidYMid meet");

    // Seed positions near each stock's cluster center so the simulation
    // settles quickly and deterministically.
    stocks.forEach((s, i) => {
        const c = centers[s.sector];
        s.x = c.x + (i % 5 - 2) * 4;
        s.y = c.y + (Math.floor(i / 5) % 5 - 2) * 4;
    });

    const tooltip = d3.select("#tooltip");
    let selectedTicker = null;
    let selectCallback = () => {};

    const nodes = svg.selectAll("g.node")
        .data(stocks, d => d.ticker)
        .join("g")
        .attr("class", "node");

    const circles = nodes.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.r)
        .attr("fill", d => color(d.sector))
        .on("mouseover", function (event, d) {
            if (d.sector === "ETF") return; // No tooltip for ETFs.
            tooltip.classed("visible", true).html(`
                <div class="tt-ticker">${d.ticker}</div>
                <div><span class="tt-label">Name:</span>${d.name}</div>
                <div><span class="tt-label">Sector:</span>${d.sector}</div>
            `);
        })
        .on("mousemove", function (event, d) {
            if (d.sector === "ETF") return;
            tooltip
                .style("left", (event.pageX + 12) + "px")
                .style("top",  (event.pageY + 12) + "px");
        })
        .on("mouseout", function () {
            tooltip.classed("visible", false);
        })
        .on("click", function (event, d) {
            selectedTicker = selectedTicker === d.ticker ? null : d.ticker;
            selectCallback(selectedTicker);
        });

    nodes.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .style("font-size", d => Math.max(9, Math.min(14, d.r / 2.2)) + "px");

    // Force simulation: cluster by sector + prevent overlap.
    const simulation = d3.forceSimulation(stocks)
        .force("x", d3.forceX(d => centers[d.sector].x).strength(0.18))
        .force("y", d3.forceY(d => centers[d.sector].y).strength(0.18))
        .force("charge", d3.forceManyBody().strength(3))
        .force("collide", d3.forceCollide(d => d.r + 2).iterations(3))
        .alpha(1)
        .alphaDecay(0.03);

    simulation.on("tick", () => {
        // Keep nodes inside the SVG viewport.
        stocks.forEach(d => {
            d.x = Math.max(d.r + 2, Math.min(WIDTH  - d.r - 2, d.x));
            d.y = Math.max(d.r + 2, Math.min(HEIGHT - d.r - 2, d.y));
        });
        nodes.attr("transform", d => `translate(${d.x},${d.y})`);
    });

    // Run enough ticks up front for stable initial layout.
    for (let i = 0; i < 300; i++) simulation.tick();
    simulation.alpha(0.3).restart();

    function highlight(ticker) {
        selectedTicker = ticker;
        circles.classed("selected", d => d.ticker === ticker);
    }

    return {
        highlight,
        onSelect(cb) { selectCallback = cb; }
    };
}

function buildTable(stocks) {
    // Sort: named sectors alphabetically, ETFs last; within a sector, by market cap desc.
    const sorted = stocks.slice().sort((a, b) => {
        const aEtf = a.sector === "ETF" ? 1 : 0;
        const bEtf = b.sector === "ETF" ? 1 : 0;
        if (aEtf !== bEtf) return aEtf - bEtf;
        if (a.sector !== b.sector) return d3.ascending(a.sector, b.sector);
        return d3.descending(a.marketCap || 0, b.marketCap || 0);
    });

    let selectedTicker = null;
    let selectCallback = () => {};

    const rows = d3.select("#stock-table tbody")
        .selectAll("tr")
        .data(sorted, d => d.ticker)
        .join("tr")
        .attr("data-ticker", d => d.ticker)
        .on("click", function (event, d) {
            selectedTicker = selectedTicker === d.ticker ? null : d.ticker;
            selectCallback(selectedTicker);
        });

    rows.append("td").attr("class", "ticker-cell").text(d => d.ticker);
    rows.append("td").text(d => d.name);
    rows.append("td").append("span")
        .attr("class", "sector-tag")
        .style("background", d => color(d.sector))
        .text(d => d.sector);
    rows.append("td").attr("class", "num").text(d => formatMarketCap(d.marketCap));

    function highlight(ticker) {
        selectedTicker = ticker;
        rows.classed("selected", d => d.ticker === ticker);
        // Scroll the selected row into view within the scrollable panel.
        if (ticker) {
            const node = document.querySelector(`#stock-table tr[data-ticker="${ticker}"]`);
            if (node) node.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
    }

    return {
        highlight,
        onSelect(cb) { selectCallback = cb; }
    };
}
